using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ──────────────────────────
// GetTypeInfo returns JsonTypeInfo (non-generic); cast to JsonTypeInfo<T>.
JsonTypeInfo<Person> personInfo =
    (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

Console.WriteLine($"Type:       {personInfo.Type.Name}");
Console.WriteLine($"Kind:       {personInfo.Kind}");
Console.WriteLine($"Properties: {personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-trip: {p}");
Console.WriteLine();

// ── 2. Probe without throwing (TryGetTypeInfo) ────────────────────
// Works for a type the resolver knows about:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"Person metadata found  – Kind={info!.Kind}");
else
    Console.WriteLine("Person metadata NOT found");

// Try a type the resolver can handle (int):
if (options.TryGetTypeInfo(typeof(int), out _))
    Console.WriteLine("int    metadata found");

// Use a resolver that deliberately knows nothing, so TryGetTypeInfo
// returns false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Person metadata found  (limited) – unexpected!");
else
    Console.WriteLine("Person metadata NOT found (limited) – expected");

// ── helper record ─────────────────────────────────────────────────
public record Person(string Name, int Age);

